import pytest
from mesh_config import compile_route_profile

def test_case_1():
    base = {
        "prefix": "/api",
        "headers": {
            "match": ["X-Tenant-Id", "Authorization", "X-Trace-Id"]
        }
    }
    env = {
        "headers": {
            "match": ["Authorization", "X-Trace-Id"]
        }
    }
    prof = compile_route_profile("mesh-1", base, env)
    assert prof["rules"]["headers"]["match"] == ["X-Tenant-Id", "Authorization", "X-Trace-Id"]
